        vector<pair<int,int>> edges;
        for(int v=2;v<=n;v++){ int u=rng()%(v-1)+1; edges.push_back({u,v}); }
        vector<ll> val(n+1);
        for(int i=1;i<=n;i++) val[i]=(ll)(rng()%21)-10;
        int R0=rng()%n+1;
        int q=rng()%12+1;
        vector<Op> ops;
        for(int i=0;i<q;i++){
            int t=rng()%12;
            Op o; o.t=t; o.c=0; o.a=1; o.b=1;
            if(t==0){ o.a=rng()%n+1; o.c=(ll)(rng()%21)-10; }
            else if(t==1){ o.a=rng()%n+1; }
            else if(t==2){ o.a=rng()%n+1; o.b=rng()%n+1; o.c=(ll)(rng()%21)-10; }
            else if(t==3||t==4||t==11){ o.a=rng()%n+1; }
            else if(t==5){ o.a=rng()%n+1; o.c=(ll)(rng()%21)-10; }
            else if(t==6){ o.a=rng()%n+1; o.b=rng()%n+1; o.c=(ll)(rng()%21)-10; }
            else if(t==7||t==8||t==10){ o.a=rng()%n+1; o.b=rng()%n+1; }
            else if(t==9){ o.a=rng()%n+1; o.b=rng()%n+1; }
            ops.push_back(o);
        }
        HLD h; vector<ll> r1=h.solve(n,edges,val,R0,ops);
        vector<ll> r2=brute(n,edges,val,R0,ops);
        if(r1!=r2){
            printf("MISMATCH test=%d n=%d\n",test,n);
