    void updateSeg(int node,int l,int r,int ql,int qr,int type,ll v){ if(ql>r||qr<l) return; if(ql<=l&&r<=qr){ if(type==0) applySet(node,l,r,v); else applyAdd(node,l,r,v); return; } push(node,l,r); int mid=(l+r)>>1; updateSeg(node<<1,l,mid,ql,qr,type,v); updateSeg(node<<1|1,mid+1,r,ql,qr,type,v); pull(node); }
    ll qs,qmn,qmx;
    void querySeg(int node,int l,int r,int ql,int qr){ if(ql>r||qr<l) return; if(ql<=l&&r<=qr){ qs+=ssum[node]; qmn=min(qmn,smn[node]); qmx=max(qmx,smx[node]); return; } push(node,l,r); int mid=(l+r)>>1; querySeg(node<<1,l,mid,ql,qr); querySeg(node<<1|1,mid+1,r,ql,qr); }
    inline bool isAnc(int a,int b){ return tin_[a]<=tin_[b] && tout_[b]<=tout_[a]; }
    int childToward(int x,int r){ while(dep_[head_[r]] > dep_[x]+1) r = par_[head_[r]]; if(dep_[r]==dep_[x]+1) return r; int d=dep_[r]-(dep_[x]+1); return ordNode[tin_[r]-d]; }
    void rebuildHLD(){ par_.assign(n+1,0); dep_.assign(n+1,0); sz_.assign(n+1,0); heavy_.assign(n+1,0); head_.assign(n+1,0); tin_.assign(n+1,0); tout_.assign(n+1,0); ordNode.assign(n+1,0); timer_=0;
        vector<int> bfs; bfs.reserve(n); vector<char> vis(n+1,0); queue<int> qu; qu.push(1); vis[1]=1; par_[1]=0; dep_[1]=0;
        while(!qu.empty()){ int u=qu.front(); qu.pop(); bfs.push_back(u); for(int v:g[u]) if(!vis[v]){ vis[v]=1; par_[v]=u; dep_[v]=dep_[u]+1; qu.push(v);} }
        for(int i=(int)bfs.size()-1;i>=0;--i){ int u=bfs[i]; sz_[u]=1; int best=0; heavy_[u]=0; for(int v:g[u]) if(v!=par_[u]){ sz_[u]+=sz_[v]; if(sz_[v]>best){best=sz_[v]; heavy_[u]=v;} } }
        // iterative DFS with explicit child lists to keep subtree contiguous
        static vector<int> idx; idx.assign(n+1,0);
        static vector<int> st; st.clear(); st.reserve(n); st.push_back(1); head_[1]=1;
        // compute child order on the fly: heavy first, then others, using adjacency and heavy
        while(!st.empty()){ int u=st.back();
            if(idx[u]==0){ tin_[u]=++timer_; ordNode[timer_]=u; }
            // find next child to push
            int nxt=0;
            if(idx[u]==0){ if(heavy_[u]){ nxt=heavy_[u]; idx[u]=1; } }
            if(!nxt){
                // push remaining children (non-heavy) one by one; we iterate adjacency each time -> could be O(deg^2)!
                nxt=0;
            }
            // fallback: precomputed children
            break;
        }
        // Use precomputed children lists (allocate once)
        static vector<vector<int>> ch; ch.assign(n+1,{});
        for(int u=2;u<=n;++u) ch[par_[u]].push_back(u);
        for(int u=1;u<=n;++u){ int h=heavy_[u]; if(!h) continue; auto&vec=ch[u]; for(int i=0;i<(int)vec.size();++i) if(vec[i]==h){ swap(vec[0],vec[i]); break; } }
        idx.assign(n+1,0); st.clear(); st.push_back(1); head_[1]=1;
        while(!st.empty()){ int u=st.back(); if(idx[u]==0){ tin_[u]=++timer_; ordNode[timer_]=u; }
            if(idx[u]<(int)ch[u].size()){ int v=ch[u][idx[u]++]; head_[v]=(v==heavy_[u])?head_[u]:v; st.push_back(v); } else { tout_[u]=timer_; st.pop_back(); } }
    }
    void subUpdate(int x,int type,ll v){ if(x==R){ updateSeg(1,1,n,1,n,type,v); } else if(isAnc(x,R)){ int c=childToward(x,R); if(tin_[c]>1) updateSeg(1,1,n,1,tin_[c]-1,type,v); if(tout_[c]<n) updateSeg(1,1,n,tout_[c]+1,n,type,v); } else updateSeg(1,1,n,tin_[x],tout_[x],type,v); }
    void subQuery(int x){ qs=0; qmn=LINF; qmx=-LINF; if(x==R){ querySeg(1,1,n,1,n); } else if(isAnc(x,R)){ int c=childToward(x,R); if(tin_[c]>1) querySeg(1,1,n,1,tin_[c]-1); if(tout_[c]<n) querySeg(1,1,n,tout_[c]+1,n); } else querySeg(1,1,n,tin_[x],tout_[x]); }
    void pathUpdate(int x,int y,int type,ll v){ while(head_[x]!=head_[y]){ if(dep_[head_[x]]<dep_[head_[y]]) swap(x,y); updateSeg(1,1,n,tin_[head_[x]],tin_[x],type,v); x=par_[head_[x]]; } if(dep_[x]>dep_[y]) swap(x,y); updateSeg(1,1,n,tin_[x],tin_[y],type,v); }
    void pathQuery(int x,int y){ qs=0; qmn=LINF; qmx=-LINF; while(head_[x]!=head_[y]){ if(dep_[head_[x]]<dep_[head_[y]]) swap(x,y); querySeg(1,1,n,tin_[head_[x]],tin_[x]); x=par_[head_[x]]; } if(dep_[x]>dep_[y]) swap(x,y); querySeg(1,1,n,tin_[x],tin_[y]); }
    void run(int nn, vector<pair<int,int>>& edges, vector<ll>& val, int R0, vector<Op>& ops){ n=nn; g.assign(n+1,{}); for(auto&e:edges){ g[e.first].insert(e.second); g[e.second].insert(e.first); } rebuildHLD();
        int sz4=4*n+5; ssum.assign(sz4,0); smn.assign(sz4,0); smx.assign(sz4,0); ladd.assign(sz4,0); lset.assign(sz4,0); hset.assign(sz4,0);
        { vector<ll> a(n+1); for(int v=1;v<=n;v++) a[tin_[v]]=val[v]; buildSeg(1,1,n,a); }
        R=R0; cur.assign(n+1,0); seg_a.assign(n+1,0); col.assign(n+1,0); ll sink=0;
        for(auto&op:ops){ if(op.t==0){ subUpdate(op.a,0,op.c); } else if(op.t==1){ R=op.a; } else if(op.t==2){ pathUpdate(op.a,op.b,0,op.c); }
            else if(op.t==3){ subQuery(op.a); sink+=qmn; } else if(op.t==4){ subQuery(op.a); sink+=qmx; }
            else if(op.t==5){ subUpdate(op.a,1,op.c); } else if(op.t==6){ pathUpdate(op.a,op.b,1,op.c); }
            else if(op.t==7){ pathQuery(op.a,op.b); sink+=qmn; } else if(op.t==8){ pathQuery(op.a,op.b); sink+=qmx; }
            else if(op.t==9){ int x=op.a,y=op.b; if(x==R) continue; bool xancR=isAnc(x,R); int p; if(xancR) p=childToward(x,R); else p=par_[x];
                bool yin; if(xancR){ int c=childToward(x,R); yin=!isAnc(c,y); } else yin=isAnc(x,y); if(yin) continue; if(y==p) continue;
                collect(1,1,n,col); for(int v=1;v<=n;v++) cur[v]=col[tin_[v]];
                g[x].erase(p); g[p].erase(x); g[x].insert(y); g[y].insert(x); rebuildHLD();
                for(int v=1;v<=n;v++) seg_a[tin_[v]]=cur[v]; buildSeg(1,1,n,seg_a); }
            else if(op.t==10){ pathQuery(op.a,op.b); sink+=qs; } else if(op.t==11){ subQuery(op.a); sink+=qs; } }
        printf("sink=%lld\n",sink);
    }
};
