            else if(op.t==3){ subQuery(op.a); out.push_back(qmn); } else if(op.t==4){ subQuery(op.a); out.push_back(qmx); }
            else if(op.t==5){ subUpdate(op.a,1,op.c); } else if(op.t==6){ pathUpdate(op.a,op.b,1,op.c); }
            else if(op.t==7){ pathQuery(op.a,op.b); out.push_back(qmn); } else if(op.t==8){ pathQuery(op.a,op.b); out.push_back(qmx); }
