vector<ll> brute(int n, vector<pair<int,int>> edges, vector<ll> val, int R0, vector<Op>& ops){
    vector<set<int>> g(n+1); for(auto&e:edges){ g[e.first].insert(e.second); g[e.second].insert(e.first); }
    int R=R0; vector<ll> out;
    auto getPar=[&](int root){ vector<int> par(n+1,0); vector<char> vis(n+1,0); queue<int> qu; qu.push(root); vis[root]=1; par[root]=0;
        while(!qu.empty()){ int u=qu.front(); qu.pop(); for(int v:g[u]) if(!vis[v]){ vis[v]=1; par[v]=u; qu.push(v);} } return par; };
    for(auto&op:ops){ int t=op.t;
        if(t==1){ R=op.a; continue; }
        if(t==9){ int x=op.a,y=op.b; if(x==R) continue; auto par=getPar(R); int p=par[x];
            vector<int> st; st.push_back(x); vector<char> vis(n+1,0); vis[x]=1; if(p) vis[p]=1; bool yin=false;
            while(!st.empty()){ int u=st.back(); st.pop_back(); if(u==y) yin=true; for(int v:g[u]) if(!vis[v]){ vis[v]=1; st.push_back(v);} }
            if(yin) continue; g[x].erase(p); g[p].erase(x); g[x].insert(y); g[y].insert(x); continue; }
        if(t==0||t==3||t==4||t==5||t==11){ int x=op.a; auto par=getPar(R);
            vector<int> st; st.push_back(x); vector<char> vis(n+1,0); vis[x]=1; if(par[x]) vis[par[x]]=1; vector<int> nodes;
            while(!st.empty()){ int u=st.back(); st.pop_back(); nodes.push_back(u); for(int v:g[u]) if(!vis[v]){ vis[v]=1; st.push_back(v);} }
            if(t==0){ for(int u:nodes) val[u]=op.c; } else if(t==5){ for(int u:nodes) val[u]+=op.c; }
            else if(t==3){ ll mn=LINF; for(int u:nodes) mn=min(mn,val[u]); out.push_back(mn); }
            else if(t==4){ ll mx=-LINF; for(int u:nodes) mx=max(mx,val[u]); out.push_back(mx); }
            else if(t==11){ ll s=0; for(int u:nodes) s+=val[u]; out.push_back(s); } continue; }
        int x=op.a,y=op.b; auto par=getPar(R);
        vector<int> dep(n+1,0); { queue<int> qu; qu.push(R); vector<char> vis(n+1,0); vis[R]=1; while(!qu.empty()){ int u=qu.front(); qu.pop(); for(int v:g[u]) if(!vis[v]){ vis[v]=1; dep[v]=dep[u]+1; qu.push(v);} } }
        int a=x,b=y; while(dep[a]>dep[b]) a=par[a]; while(dep[b]>dep[a]) b=par[b]; while(a!=b){ a=par[a]; b=par[b]; } int lca=a;
        vector<int> path; { int u=x; while(u!=lca){ path.push_back(u); u=par[u]; } path.push_back(lca); }
        { int u=y; vector<int> tmp; while(u!=lca){ tmp.push_back(u); u=par[u]; } for(int i=(int)tmp.size()-1;i>=0;i--) path.push_back(tmp[i]); }
        if(t==2){ for(int u:path) val[u]=op.c; } else if(t==6){ for(int u:path) val[u]+=op.c; }
        else if(t==7){ ll mn=LINF; for(int u:path) mn=min(mn,val[u]); out.push_back(mn); }
        else if(t==8){ ll mx=-LINF; for(int u:path) mx=max(mx,val[u]); out.push_back(mx); }
        else if(t==10){ ll s=0; for(int u:path) s+=val[u]; out.push_back(s); } }
    return out;
}

