            printf("vals:"); for(int i=1;i<=n;i++) printf(" %lld",val[i]); printf("\n"); printf("R0=%d q=%d\n",R0,q);
            for(auto&o:ops) printf("op %d %d %d %lld\n",o.t,o.a,o.b,o.c);
            printf("HLD:"); for(ll v:r1) printf(" %lld",v); printf("\n"); printf("BRT:"); for(ll v:r2) printf(" %lld",v); printf("\n"); return 0; }
    }
    printf("ALL OK\n"); return 0;
