    void subUpdate(int x,int type,ll v){ if(x==R){ updateSeg(1,1,n,1,n,type,v); } else if(isAnc(x,R)){ int c=childToward(x,R); if(tin_[c]>1) updateSeg(1,1,n,1,tin_[c]-1,type,v); if(tout_[c]<n) updateSeg(1,1,n,tout_[c]+1,n,type,v); } else updateSeg(1,1,n,tin_[x],tout_[x],type,v); }
    void subQuery(int x){ qs=0; qmn=LINF; qmx=-LINF; if(x==R){ querySeg(1,1,n,1,n); } else if(isAnc(x,R)){ int c=childToward(x,R); if(tin_[c]>1) querySeg(1,1,n,1,tin_[c]-1); if(tout_[c]<n) querySeg(1,1,n,tout_[c]+1,n); } else querySeg(1,1,n,tin_[x],tout_[x]); }
    void pathUpdate(int x,int y,int type,ll v){ while(head_[x]!=head_[y]){ if(dep_[head_[x]]<dep_[head_[y]]) swap(x,y); updateSeg(1,1,n,tin_[head_[x]],tin_[x],type,v); x=par_[head_[x]]; } if(dep_[x]>dep_[y]) swap(x,y); updateSeg(1,1,n,tin_[x],tin_[y],type,v); }
    void pathQuery(int x,int y){ qs=0; qmn=LINF; qmx=-LINF; while(head_[x]!=head_[y]){ if(dep_[head_[x]]<dep_[head_[y]]) swap(x,y); querySeg(1,1,n,tin_[head_[x]],tin_[x]); x=par_[head_[x]]; } if(dep_[x]>dep_[y]) swap(x,y); querySeg(1,1,n,tin_[x],tin_[y]); }
    vector<ll> solve(int nn, vector<pair<int,int>>& edges, vector<ll>& val, int R0, vector<Op>& ops){
        n=nn; g.assign(n+1,{}); for(auto&e:edges){ g[e.first].insert(e.second); g[e.second].insert(e.first); } rebuildHLD();
        int sz4=4*n+5; ssum.assign(sz4,0); smn.assign(sz4,0); smx.assign(sz4,0); ladd.assign(sz4,0); lset.assign(sz4,0); hset.assign(sz4,0);
        { vector<ll> a(n+1); for(int v=1;v<=n;v++) a[tin_[v]]=val[v]; buildSeg(1,1,n,a); }
