        int R0=rng()%n+1; int q=rng()%50+1; vector<Op> ops;
        for(int i=0;i<q;i++){ int t=rng()%12; Op o; o.t=t; o.c=0; o.a=1; o.b=1;
            if(t==0){ o.a=rng()%n+1; o.c=(ll)(rng()%21)-10; } else if(t==1){ o.a=rng()%n+1; }
            else if(t==2){ o.a=rng()%n+1; o.b=rng()%n+1; o.c=(ll)(rng()%21)-10; }
            else if(t==3||t==4||t==11){ o.a=rng()%n+1; }
            else if(t==5){ o.a=rng()%n+1; o.c=(ll)(rng()%21)-10; }
            else if(t==6){ o.a=rng()%n+1; o.b=rng()%n+1; o.c=(ll)(rng()%21)-10; }
            else if(t==7||t==8||t==10){ o.a=rng()%n+1; o.b=rng()%n+1; }
            else if(t==9){ o.a=rng()%n+1; o.b=rng()%n+1; } ops.push_back(o); }
        HLD h; vector<ll> r1=h.solve(n,edges,val,R0,ops); vector<ll> r2=brute(n,edges,val,R0,ops);
        if(r1!=r2){ printf("MISMATCH test=%d n=%d\n",test,n); return 0; }
    }
    printf("ALL OK\n");
    // perf
    int n=100000,q=100000; mt19937 rg(1);
    vector<pair<int,int>> edges; for(int v=2;v<=n;v++){ int u=rg()%(v-1)+1; edges.push_back({u,v}); }
    vector<ll> val(n+1); for(int i=1;i<=n;i++) val[i]=rg()%1000;
    for(int cnt : {500, 2000}){
        vector<Op> ops; ops.reserve(q);
        for(int i=0;i<q;i++){ Op o; o.t=0; o.a=rg()%n+1; o.b=0; o.c=(ll)(rg()%100)-50; ops.push_back(o); }
        int placed=0; for(int i=0;i<q && placed<cnt;i++){ int x=rg()%(n-1)+2; int y=rg()%n+1; if(y==x) continue; Op o; o.t=9; o.a=x; o.b=y; ops[i]=o; placed++; }
        HLD h; auto t0=chrono::steady_clock::now(); auto res=h.solve(n,edges,val,1,ops); auto t1=chrono::steady_clock::now();
        printf("op9=%d time=%lld ms (out %d)\n",cnt,(ll)chrono::duration_cast<chrono::milliseconds>(t1-t0).count(),(int)res.size());
    }
    return 0;
}

